package com.aidevos.orchestrator.qualitygate;
import java.time.Instant; import java.util.Optional; import com.aidevos.orchestrator.audit.AuditService; import com.aidevos.orchestrator.change.*; import com.aidevos.orchestrator.commit.*; import com.aidevos.orchestrator.remote.*; import com.aidevos.orchestrator.workspace.WorkspaceService; import com.aidevos.orchestrator.workspace.git.GitCommandExecutor; import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertThrows; import static org.mockito.Mockito.*;
class QualityGateGitEnforcementTest {
	@Test void blockPreventsCommitBeforeGitExecutor(){QualityGateService gate=mock(QualityGateService.class);doThrow(new IllegalStateException("Quality Gate denied")).when(gate).assertAllowed("task-1");ChangeService changes=mock(ChangeService.class);when(changes.getChange("change-1")).thenReturn(Optional.of(approvedChange()));GitCommandExecutor git=mock(GitCommandExecutor.class);CommitService service=new CommitService(mock(CommitRepository.class),changes,mock(WorkspaceService.class),git,AuditService.noop());service.setQualityGateService(gate);assertThrows(IllegalStateException.class,()->service.commit("change-1"));verifyNoInteractions(git);}
	@Test void blockPreventsPushBeforeGitExecutor(){QualityGateService gate=mock(QualityGateService.class);doThrow(new IllegalStateException("Quality Gate denied")).when(gate).assertAllowed("task-1");CommitRecord commit=new CommitRecord("commit-1","change-1","task-1","workspace-1","main","m",Instant.now());commit.markCommitting();commit.markSuccess("abc");CommitService commits=mock(CommitService.class);when(commits.getCommit("commit-1")).thenReturn(Optional.of(commit));GitCommandExecutor git=mock(GitCommandExecutor.class);RemoteGitService service=new RemoteGitService(mock(RemoteRepository.class),commits,mock(WorkspaceService.class),git,AuditService.noop());service.setQualityGateService(gate);assertThrows(IllegalStateException.class,()->service.push("commit-1",null));verifyNoInteractions(git);}
	private ChangeSet approvedChange(){ChangeSet c=new ChangeSet("change-1","task-1","workspace-1","project-1",null,"main","","",0,0,0,0,0,0,Instant.now());c.markReviewing();c.markApproved("reviewer");return c;}
}
